PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE books (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, authors TEXT NOT NULL DEFAULT '', series TEXT NOT NULL DEFAULT '', series_index REAL NOT NULL DEFAULT 0, publisher TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT '', isbn TEXT NOT NULL DEFAULT '', published TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', path TEXT NOT NULL DEFAULT '', added INTEGER NOT NULL, has_cover INTEGER NOT NULL DEFAULT 0, paper INTEGER NOT NULL DEFAULT 0, shelf TEXT NOT NULL DEFAULT '', rating INTEGER NOT NULL DEFAULT 0, finished TEXT NOT NULL DEFAULT '', identifiers TEXT NOT NULL DEFAULT '{}');
INSERT INTO books VALUES(1,'The Sea Wall','Ann Author','The Coast',1,'','','','','','fiction, sea','Ann Author/The Sea Wall (1)',1794694143,0,0,'reading',4,'','{}');
INSERT INTO books VALUES(2,'A Paper Book','Bo Writer','',0,'','','','','','','Bo Writer/A Paper Book (2)',1794694143,0,1,'read',5,'2026-03-01','{}');
INSERT INTO books VALUES(3,'One For Later','Cy Guide','',0,'','','','','','','Cy Guide/One For Later (3)',1794694143,0,0,'to-read',0,'','{}');
CREATE TABLE formats (book_id INTEGER NOT NULL REFERENCES books(id) ON DELETE CASCADE, format TEXT NOT NULL, file TEXT NOT NULL, size INTEGER NOT NULL, hash TEXT NOT NULL, PRIMARY KEY (book_id, format));
INSERT INTO formats VALUES(1,'md','The Sea Wall - Ann Author.md',90,'90afdfbc470999c9ecfbd104b951a2240e6fed45f90705c9efab8317f2b0734a');
CREATE TABLE progress (book_id INTEGER PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE, section INTEGER NOT NULL, fraction REAL NOT NULL, percent REAL NOT NULL, updated INTEGER NOT NULL);
INSERT INTO progress VALUES(1,1,0.5,60,1794694143);
CREATE TABLE annotations (id INTEGER PRIMARY KEY AUTOINCREMENT, book_id INTEGER NOT NULL REFERENCES books(id) ON DELETE CASCADE, kind TEXT NOT NULL, section INTEGER NOT NULL, fraction REAL NOT NULL, text TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
INSERT INTO annotations VALUES(1,1,'bookmark',1,0.5,'The lamps','',1794694143);
CREATE TABLE removed (hash TEXT PRIMARY KEY, removed_at INTEGER NOT NULL);
CREATE TABLE notes (book_id INTEGER NOT NULL REFERENCES books(id) ON DELETE CASCADE, kind TEXT NOT NULL, section INTEGER NOT NULL, fraction REAL NOT NULL, text TEXT NOT NULL, updated INTEGER NOT NULL, PRIMARY KEY (book_id, kind));
INSERT INTO notes VALUES(1,'furthest',1,0.5,'',1794694143);
CREATE TABLE graph_nodes (id INTEGER PRIMARY KEY AUTOINCREMENT, scope TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL, name TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', data TEXT NOT NULL DEFAULT '{}', book_id INTEGER REFERENCES books(id) ON DELETE CASCADE, updated INTEGER NOT NULL);
INSERT INTO graph_nodes VALUES(1,'','book','The Sea Wall','','{"held":"digital","made":"039a5e68bc2dc2ee7aa6b36b8445d87899fbffe5","percent_read":60,"rating":4,"status":"reading"}',1,1794694143);
INSERT INTO graph_nodes VALUES(2,'','author','Ann Author','','{}',NULL,1794694143);
INSERT INTO graph_nodes VALUES(3,'','series','The Coast','','{}',NULL,1794694143);
INSERT INTO graph_nodes VALUES(4,'','tag','fiction','','{}',NULL,1794694143);
INSERT INTO graph_nodes VALUES(5,'','tag','sea','','{}',NULL,1794694143);
INSERT INTO graph_nodes VALUES(6,'','book','A Paper Book','','{"finished":"2026-03-01","held":"paper","made":"755c1942ef7d00f55fdcc96cbac02ee53e60d6ce","rating":5,"status":"read"}',2,1794694143);
INSERT INTO graph_nodes VALUES(7,'','author','Bo Writer','','{}',NULL,1794694143);
